import {
  FlatList,
  Platform,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import {IReceiptItem} from '../../../../../model/interface/receipt.interface';
import TextCM from '../../../../components/Text';
import {Color, Font, NavigationName} from '../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {useEffect, useRef, useState} from 'react';
import {DateUtils} from '../../../../../utils';
import {listRequestStatus, listStatusReceipt} from '../modal-filter/helper';
import {statusRequestTagProperties} from '../../../detail-receipt/helper';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {useNavigation} from '@react-navigation/native';
import Toast from 'react-native-toast-message';
import {
  useReceiptServices,
  useTicketServices,
} from '../../../../../hooks/apiHooks/useAPI';
import {List_Action} from './helper';
import {useCatalogStore} from '../../../../../zutand/catalogStore';
import {useServiceStore} from '../../../../../zutand/servicesStore';
type Props = {
  receipt: IReceiptItem;
};

const ReceiptItem = ({receipt}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [widthOfCard, setWidthOfCard] = useState(0);
  const data = receipt.data;

  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const {width} = useWindowDimensions();

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const ReceiptService = useReceiptServices();
  const {listADJUSTMENT_CODE, listALTERNATIVE_CODE} = useCatalogStore();
  const {listTicketByModelerId, listAjustment, listReplacement, listServices} =
    useServiceStore();

  const TicketService = useTicketServices();
  const navigateToDetailReceiptScreen = (id: string) => {
    navigation.navigate(NavigationName.DetailReceiptScreen, {id});
  };

  const DashLine = () => {
    return (
      <Svg height="10" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Line
          x1="20"
          y1="5"
          x2={widthOfCard - 20}
          y2="5"
          stroke="#cbcbcb"
          strokeWidth="1"
          strokeDasharray="8.8"
        />
      </Svg>
    );
  };

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = listStatusReceipt.find((item: any) => item.value === status);
    } else if (type === 'REQUEST') {
      properties = statusRequestTagProperties.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    } else {
      properties = listRequestStatus.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View style={{flex: 1}} />
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {t(`BLDT.${properties?.value}`)}
            </TextCM>
          </View>
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={{flex: 1}} />
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: '#d94936'}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
      </View>
    );
  };

  const handleGenerateNumber = async (id: string) => {
    if (isRegenerating) {
      return;
    }
    setIsRegenerating(true);
    timeoutRef.current = setTimeout(() => {
      setIsRegenerating(false);
      timeoutRef.current = null;
    }, 30 * 1000);
    const dataResp = await ReceiptService.reGenerateNumberReceipt(id);
    if (dataResp) {
      Toast.show({
        type: 'success',
        text1: t('CM.noti'),
        text2: t('CM.success'),
      });
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };

  const checkDisableAction = (action: string) => {
    if (
      (action === 'edit' || action === 'delete') &&
      data.status === 'draft_receipt'
    )
      return false;
    if (
      (action === 'replace' || action == 'ajustment') &&
      data.status === 'released_receipt'
    )
      return false;
    if (
      action === 'cancel' &&
      data.status === 'processing_receipt' &&
      data.flowStatus === 'approval_receipt'
    )
      return false;
    return true;
  };

  const handleAction = (action: string) => {
    if (action === 'edit') {
      navigation.navigate(NavigationName.CreateTicketScreen, {
        dataTicket: {
          id: data.ticketId,
          modelerId: data.modelerId,
          workFlowId: data.workFlowId,
          flowName: data.name,
        },
        action: 'edit',
      });
    }
    if (action === 'ajustment') {
      handleActionAjustment();
    }
    if (action === 'replace') {
      handleActionReplace();
    }

    if (action === 'delete') {
      handleActionDelete();
    }
  };

  const handleActionDelete = () => {
    Toast.show({
      type: 'info',
      text1: t('CM.info'),
      text2: 'Tính năng đang phát triển',
    });
  };

  const handleActionAjustment = () => {
    const modelers = listServices.flatMap(s => s.modelers);
    const rootModeler = modelers.find(
      m => m.id === data.workFlowId && m.modelerId === data.modelerId,
    );
    const alternativeCode = listADJUSTMENT_CODE.find(
      s => s?.['textField_input-1'] === rootModeler?.keyValue,
    )?.['textField_input-2'];
    const modelerByAlternativeCode = listTicketByModelerId?.find(
      d => d?.keyValue === alternativeCode,
    );
    const alternativeModeler = listAjustment
      ?.flatMap(s => s.modelers)
      ?.find(m => m.modelerId === modelerByAlternativeCode?.id);
    if (alternativeCode && alternativeModeler) {
      navigation.navigate(NavigationName.CreateTicketScreen, {
        dataTicket: {
          modelerId: alternativeModeler?.modelerId,
          workFlowId: alternativeModeler?.id,
          flowName: data.name,
        },
        relatedTicket: data.ticketId,
        action: 'ajustment',
      });
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Không tìm thấy quy trình điều chỉnh',
      });
    }
  };

  const handleActionReplace = () => {
    const modelers = listServices.flatMap(s => s.modelers);
    const rootModeler = modelers.find(
      m => m.id === data.workFlowId && m.modelerId === data.modelerId,
    );
    const keyValueOfRootModeler = (
      listTicketByModelerId?.find(m => m.id === rootModeler?.modelerId) as any
    )?.keyValue;
    const replaceCode = listALTERNATIVE_CODE.find(
      s => s?.['textField_input-1'] === keyValueOfRootModeler,
    )?.['textField_input-2'];

    const modelerByReplaceCode = listTicketByModelerId?.find(
      d => d?.keyValue === replaceCode,
    );

    const replaceModeler = listReplacement
      ?.flatMap(s => s.modelers)
      ?.find(m => m.modelerId === modelerByReplaceCode?.id);
    if (replaceCode && replaceModeler) {
      navigation.navigate(NavigationName.CreateTicketScreen, {
        dataTicket: {
          modelerId: replaceModeler?.modelerId,
          workFlowId: replaceModeler?.id,
          flowName: data.name,
        },
        relatedTicket: data.ticketId,
        action: 'replace',
      });
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Không tìm thấy quy trình thay thế',
      });
    }
  };

  return (
    <View style={styles.container}>
      <TouchableOpacity
        onPress={() => navigateToDetailReceiptScreen(data.id)}
        activeOpacity={Platform.OS === 'ios' ? 0.8 : 0.9}>
        <View
          onLayout={event => {
            const {width} = event.nativeEvent.layout;
            setWidthOfCard(width);
          }}
          style={[
            styles.card,
            styles.radiusTop,
            // styles.shadowTop,
            // styles.shadowLeft,
            // styles.shadowRight,
          ]}>
          <View style={styles.header}>
            <View style={{flex: 1, columnGap: 8}}>
              <TextCM style={styles.title}>{data.name || '---'}</TextCM>
              <TextCM style={styles.idNumber}>{data.caseCode || '---'}</TextCM>
            </View>
            {data.status === 'error_receipt' && (
              <TouchableOpacity
                onPress={() => handleGenerateNumber(data.id)}
                style={[styles.capSoStyle, isRegenerating && styles.disable]}>
                <TextCM
                  style={{color: Color.White, fontFamily: Font.InterMedium500}}>
                  {t('BLDT.arithmetic')}
                </TextCM>
              </TouchableOpacity>
            )}
          </View>
        </View>

        <DashLine />

        <View
          style={[
            styles.card,
            styles.radiusBot,
            // styles.shadowBottom,
            // styles.shadowLeft,
            // styles.shadowRight,
          ]}>
          <View style={styles.receiptTypeSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.receiptTypeLabel}>
                {t('BLDT.type_receipt')}
              </TextCM>
            </View>
            <View style={{flex: 1}}>
              <TextCM style={styles.receiptTypeCode}>
                {data.type || '---'}
              </TextCM>
            </View>
          </View>

          <View style={styles.dateSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.dateLabel}>{t('CM.createDateCard')}</TextCM>
            </View>
            <TextCM style={styles.dateValue}>
              {DateUtils.convertDateToDDMMYYYY_H_M(data.createdDate) || '---'}
            </TextCM>
          </View>

          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>
                {t('BLDT.flow_status')}
              </TextCM>
            </View>
            {data.flowStatus && (
              <StatusTag status={data?.flowStatus} type={'REQUEST'} />
            )}
          </View>
          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>
                {t('BLDT.receipt_status')}
              </TextCM>
            </View>
            {data.status && <StatusTag status={data.status} type={'DEFAULT'} />}
          </View>
          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>
                {t('BLDT.funding_status')}
              </TextCM>
            </View>
            {data.requestStatus && (
              <StatusTag status={data.requestStatus} type={'MIX'} />
            )}
          </View>
        </View>
      </TouchableOpacity>

      <DashLine />

      <FlatList
        style={styles.ctnListAction}
        data={List_Action}
        renderItem={({item}) => (
          <TouchableOpacity
            onPress={() => handleAction(item.value)}
            disabled={checkDisableAction(item.value)}
            style={{
              ...styles.ctnAction,
              width: (width - 48) / List_Action.length,
            }}>
            {item.icon}
            <TextCM
              style={[
                styles.txtAction,
                checkDisableAction(item.value) && {
                  color: '#95a1b5',
                  fontFamily: Font.InterMedium500,
                },
              ]}>
              {item.label}
            </TextCM>
          </TouchableOpacity>
        )}
      />
    </View>
  );
};

export default ReceiptItem;
