import {useCallback, useState} from 'react';
import {ActivityIndicator, View} from 'react-native';
import TextCM from '../../components/Text';
import {useFocusEffect, useNavigation} from '@react-navigation/native';
import {Color, Font, NavigationName} from '../../../constants';
import {Icon, List, MenuGroup, MenuItem} from '@ui-kitten/components';
import {useTicketServices} from '../../../hooks/apiHooks/useAPI';
import {IServicesHome, Modeler} from './helper';
import {useAppSelector} from '../../../hooks/useRedux';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';
import {useServiceStore} from '../../../zutand/servicesStore';

type Props = {
  onClose: () => void;
};

const CreateNewScreen = ({onClose}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const {listServices} = useServiceStore();

  const handleCreate = (item: Modeler) => {
    onClose();
    navigation.navigate(NavigationName.CreateTicketScreen, {
      dataTicket: item,
    });
  };
  return (
    <>
      <List
        data={listServices}
        renderItem={({item}) => (
          <MenuGroup
            initiallyExpanded={listServices?.length === 1}
            title={props => <TextCM {...props}>{item?.serviceName}</TextCM>}>
            {item?.modelers?.map((itemModeler: Modeler) => (
              <MenuItem
                onPress={() => handleCreate(itemModeler)}
                title={props => (
                  <TextCM
                    {...props}
                    style={{
                      fontSize: 14,
                      color: Color.TextPrimary,
                      fontFamily: Font.InterRegular400,
                      flex: 1,
                      marginLeft: 16,
                    }}>
                    {itemModeler?.flowName}
                  </TextCM>
                )}
                accessoryRight={
                  <Icon
                    name="arrow-ios-forward-outline"
                    fill={Color.TextPrimary}
                    width={20}
                    height={20}
                  />
                }
              />
            ))}
          </MenuGroup>
        )}
        keyExtractor={(item, index) => index.toString()}
        ListEmptyComponent={() => (
          <View
            style={{
              alignItems: 'center',
              justifyContent: 'center',
              height: 200,
            }}>
            <TextCM>{t('CM.emptyData')}</TextCM>
          </View>
        )}
      />
    </>
  );
};

export default CreateNewScreen;
