import {CalendarRange, IndexPath} from '@ui-kitten/components';
import {create} from 'zustand';

export type ValueFilterSearch = {
  rangeDay?: CalendarRange<Date>;
  paymentMethod?: IndexPath[];
  requestStatus?: IndexPath[];
  status?: IndexPath[];
  type?: IndexPath[];
};

interface ZutandStore {
  listTypeReceipt: {label: string; value: string}[];
  listReceiptStatus: {label: string; value: string}[];
  listProcessStatus: {label: string; value: string}[];
  setListTypeReceipt: (
    listTypeReceipt: {label: string; value: string}[],
  ) => void;
  setReceiptStatus: (
    listReceiptStatus: {label: string; value: string}[],
  ) => void;
  setProcessStatus: (
    listProcessStatus: {label: string; value: string}[],
  ) => void;
}

const initialReceiptState = {
  listTypeReceipt: [],
  listReceiptStatus: [],
  listProcessStatus: [],
};

export const useReceiptZustandStore = create<ZutandStore>((set, get) => ({
  ...initialReceiptState,
  setListTypeReceipt: (listTypeReceipt: {label: string; value: string}[]) => {
    set({listTypeReceipt});
  },
  setReceiptStatus: (listReceiptStatus: {label: string; value: string}[]) => {
    set({listReceiptStatus});
  },
  setProcessStatus: (listProcessStatus: {label: string; value: string}[]) => {
    set({listProcessStatus});
  },
}));
