import {create} from 'zustand';
import {MenuViewItem} from '../model/interface/service.interface';

interface CatalogStore {
  listADJUSTMENT_CODE: any[];
  listALTERNATIVE_CODE: any[];
  setListADJUSTMENT_CODE: (listADJUSTMENT_CODE: any[]) => void;
  setListALTERNATIVE_CODE: (listALTERNATIVE_CODE: any[]) => void;
}

const initialSettingState = {
  listADJUSTMENT_CODE: [],
  listALTERNATIVE_CODE: [],
};

export const useCatalogStore = create<CatalogStore>((set, get) => ({
  ...initialSettingState,
  setListADJUSTMENT_CODE: (listADJUSTMENT_CODE: any[]) => {
    set({listADJUSTMENT_CODE});
  },
  setListALTERNATIVE_CODE: (listALTERNATIVE_CODE: any[]) => {
    set({listALTERNATIVE_CODE});
  },
}));
